function y = fir4_fixpt(x)

%#codegen

fm = get_fimath();

h0 = fi(0.2, 0, 14, 16, fm);
h1 = fi(0.4, 0, 14, 15, fm);
h2 = fi(0.3, 0, 14, 15, fm);
h3 = fi(0.1, 0, 14, 17, fm);

persistent d1 d2 d3
if isempty(d1)
    d1 = fi(0, 0, 14, 14, fm);
    d2 = fi(0, 0, 14, 14, fm);
    d3 = fi(0, 0, 14, 14, fm);
end

% Shift register
x0 = fi(x, 0, 14, 14, fm);
x1 = fi(d1, 0, 14, 14, fm);
x2 = fi(d2, 0, 14, 14, fm);
x3 = fi(d3, 0, 14, 14, fm);

d3(:) = d2;
d2(:) = d1;
d1(:) = x;

% Fully parallel FIR
y = fi(h0*x0 + h1*x1 + h2*x2 + h3*x3, 0, 14, 14, fm);

end


function fm = get_fimath()
	fm = fimath('RoundingMethod', 'Floor',...
	     'OverflowAction', 'Wrap',...
	     'ProductMode','FullPrecision',...
	     'MaxProductWordLength', 128,...
	     'SumMode','FullPrecision',...
	     'MaxSumWordLength', 128);
end
